<?php
require_once __DIR__.'/bookkeeping.php';$supplierMode=$page==='bookkeeping-suppliers';$table=$supplierMode?'bookkeeping_suppliers':'expense_categories';$id=(int)($_GET['id']??0);$edit=$id?query('SELECT * FROM '.$table.' WHERE id=?',[$id])->fetch():null;
