$val=fn($key,$default='')=>pv($key,(string)($edit[$key]??$default));
?>
<div class="toolbar"><a class="button secondary" href="/?page=expenses">← 기장 내역</a><a class="button" href="/?page=<?=$page?>#bookkeeping-editor">＋ <?=$supplierMode?'구매처':'Account'?> 추가</a></div>
<section class="panel"><h2><?=$supplierMode?'구매처 관리':'Chart of Accounts'?></h2><p class="hint"><?=$supplierMode?'자주 사용하는 구매처부터 표시합니다. 별칭으로 지점을 같은 구매처에 연결합니다. 삭제는 목록에서 숨기는 처리이며 과거 거래·영수증은 유지합니다.':'엑셀에서 자주 쓰인 Account 순서로 시작하며, 실제 거래가 쌓이면 사용 횟수 순으로 표시합니다. Account를 수정해도 이전 거래 금액은 유지합니다. Tax treatment 변경은 집계 분류에 반영됩니다.'?></p>
<div class="table-wrap"><table><thead><tr><th><?=$supplierMode?'구매처':'Account'?></th><th><?=$supplierMode?'사용 횟수':'Tax treatment / 기본 비율'?></th><th>관리</th></tr></thead><tbody>
<?php $list=$supplierMode?query('SELECT s.*,COUNT(e.id) usage_count FROM bookkeeping_suppliers s LEFT JOIN expenses e ON e.supplier_id=s.id AND e.voided=0 GROUP BY s.id,s.name,s.name_key,s.active,s.version,s.created_at ORDER BY s.active DESC,usage_count DESC,s.name')->fetchAll():bookkeepingAccounts(false);foreach($list as $row): ?>
<tr><td><?=e($row['name'])?><?=$row['active']?'':' (사용 중지)'?></td><td><?=(int)$row['usage_count']?>회<?php if(!$supplierMode): ?> · <?=e($row['tax_type'])?> · Income Tax <?=(float)$row['default_deductible_pct']?>% · ITC limit <?=(float)$row['default_itc_pct']?>%<?php endif ?></td><td class="bookkeeping-row-actions"><a class="button secondary" href="/?page=<?=$page?>&id=<?=(int)$row['id']?>#bookkeeping-editor"><?=$row['active']?'수정':'수정·복원'?></a><?php if($row['active']): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=(int)$row['id']?>"><input type="hidden" name="version" value="<?=(int)$row['version']?>"><button name="action" value="<?=$supplierMode?'supplier_delete':'accounting_delete'?>" class="button danger" data-confirm="이 항목을 목록에서 숨길까요? 이전 거래와 영수증은 유지합니다.">삭제</button></form><?php endif ?></td></tr>
<?php endforeach ?></tbody></table></div></section>
<section class="panel minor-action" id="bookkeeping-editor"><h2><?=$edit?'수정·복원':'새 항목 등록'?></h2><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="<?=$supplierMode?'supplier_save':'accounting_save'?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?=(int)($edit['version']??0)?>"><label><?=$supplierMode?'대표 구매처 이름':'Account name'?><input name="name" maxlength="<?=$supplierMode?150:100?>" value="<?=e($val('name'))?>" required></label>
<?php if($supplierMode): $aliases=$id?query('SELECT label FROM bookkeeping_supplier_aliases WHERE supplier_id=? ORDER BY id',[$id])->fetchAll(PDO::FETCH_COLUMN):[]; ?><label>같은 구매처로 연결할 별칭 (한 줄에 하나)<textarea name="aliases" rows="5" maxlength="4000" placeholder="Costco Business Center&#10;Costco Merivale&#10;Costco Strandherd"><?=e(pv('aliases',implode("\n",$aliases)))?></textarea></label><p class="hint">Costco 지점은 기본적으로 Costco에 연결됩니다. 다른 이름은 여기서 별칭을 등록합니다. 기존 별칭을 다른 구매처로 옮기려면 아래 통합 기능을 사용하세요.</p>
<?php else: ?><div class="form-grid"><label>Tax treatment<select name="tax_type"><?php foreach(['operating'=>'Operating Expense','inventory'=>'Inventory / COGS Purchases','capital'=>'Capital Asset / CCA Review','review'=>'Tax Review Required'] as $key=>$label): ?><option value="<?=$key?>" <?=$val('tax_type','operating')===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><label>Income Tax reference / line (선택)<input name="income_tax_line" maxlength="30" value="<?=e($val('income_tax_line'))?>"></label><label>기본 Income Tax Deductible (%)<input name="default_deductible_pct" type="number" min="0" max="100" step="0.01" value="<?=e($val('default_deductible_pct','100'))?>" required></label><label>기본 ITC Limit (%)<input name="default_itc_pct" type="number" min="0" max="100" step="0.01" value="<?=e($val('default_itc_pct','100'))?>" required></label><label>동일 사용 횟수일 때 순서<input name="sort_order" type="number" min="0" max="9999" value="<?=e($val('sort_order','999'))?>" required></label></div><p class="hint">기본 비율은 이후 입력의 초깃값입니다. 기존 거래의 비율은 자동 변경하지 않습니다. Meals는 일반적인 기본값 50%이며 예외·사업 사용분·ITC eligibility는 각 거래에서 확인합니다.</p><?php endif ?>
<button class="button">저장<?=$edit?'·사용 재개':''?></button></form></section>
<?php if($supplierMode&&$edit&&$edit['active']): ?><section class="panel minor-action"><h2>다른 구매처로 통합</h2><p>이 구매처의 거래와 별칭을 선택한 대표 구매처에 연결합니다. 원래 영수증 표시명·금액·증빙은 유지합니다.</p><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="supplier_merge"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?=(int)$edit['version']?>"><label>대표 구매처<select name="target_id" required><option value="">선택하세요</option><?php foreach(bookkeepingSuppliers() as $s): if((int)$s['id']===$id)continue; ?><option value="<?=(int)$s['id']?>"><?=e($s['name'])?></option><?php endforeach ?></select></label><button class="button secondary" data-confirm="거래와 별칭을 선택한 구매처로 통합할까요? 이력은 남습니다.">구매처 통합</button></form></section><?php endif ?>
